// Variants trade off: "card" is the default padded, centered preview; "canvas"
// gives floating / overlay components more room; "wide" lets dense layouts span
// the full preview width.
type FrameVariant = "card" | "canvas" | "wide";

function Frame({
  children,
  variant = "card",
  maxWidth,
}: {
  children: React.ReactNode;
  variant?: FrameVariant;
  maxWidth?: number;
}) {
  const base =
    "relative w-full rounded-xl border border-neutral-200/80 bg-white p-6 dark:border-zinc-800/80 dark:bg-zinc-950";
  const variants: Record<FrameVariant, string> = {
    card: "flex min-h-[320px] items-center justify-center",
    canvas: "flex min-h-[420px] items-end justify-center overflow-hidden",
    wide: "flex min-h-[360px] items-center justify-center",
  };
  return (
    <div className={`${base} ${variants[variant]}`}>
      <div className="w-full" style={maxWidth ? { maxWidth } : undefined}>
        {children}
      </div>
    </div>
  );
}

